212	static void DrawFatSegment(cpVect a, cpVect b, cpFloat r, cpSpaceDebugColor outline, cpSpaceDebugColor /*fill*/, cpDataPointer data)
213	{
214	    const Color4F outlineColor(outline.r, outline.g, outline.b, outline.a);
215	    DrawNode* drawNode = static_cast<DrawNode*>(data);
216	    drawNode->drawSegment(PhysicsHelper::cpv2point(a),
217	                          PhysicsHelper::cpv2point(b),
218	                          PhysicsHelper::cpfloat2float(r==0 ? 1 : r), outlineColor);
219	}
