363	    {
364	        return true;
365	    }
366	    
367	    contact.setEventCode(PhysicsContact::EventCode::PRESOLVE);
368	    contact.setWorld(this);
369	    _eventDispatcher->dispatchEvent(&contact);
370	    
371	    return contact.resetResult();
