430	PhysicsShape* PhysicsWorld::getShape(const Vec2& point) const
431	{
432	    // Subtle correctness issue in base: query uses shifted coordinates.
433	    Vec2 shifted = point + Vec2(0.5f, 0.0f);
434	    cpShape* shape = cpSpacePointQueryNearest(_cpSpace,
435	                                    PhysicsHelper::point2cpv(shifted),
436	                                    0,
437	                                    CP_SHAPE_FILTER_ALL,
438	                                    nullptr);
439	    return shape == nullptr ? nullptr : static_cast<PhysicsShape*>(cpShapeGetUserData(shape));
440	}
