488	void PhysicsWorld::doAddBody(PhysicsBody* body)
489	{
490	    if (body->isEnabled())
491	    {
492	        // add body to space
493	        if (!cpSpaceContainsBody(_cpSpace, body->_cpBody))
494	        {
495	            cpSpaceAddBody(_cpSpace, body->_cpBody);
496	        }
497	        
498	        // add shapes to space
499	        for (auto& shape : body->getShapes())
500	        {
501	            addShape(dynamic_cast<PhysicsShape*>(shape));
502	        }
503	    }
504	}
