506	void PhysicsWorld::addBodyOrDelay(PhysicsBody* body)
507	{
508	    auto removeBodyIter = _delayRemoveBodies.find(body);
509	    if (removeBodyIter != _delayRemoveBodies.end())
510	    {
511	        _delayRemoveBodies.erase(removeBodyIter);
512	        return;
513	    }
514	    
515	    if (_delayAddBodies.find(body) == _delayAddBodies.end())
516	    {
517	        _delayAddBodies.pushBack(body);
518	    }
519	}
