544	void PhysicsWorld::removeBody(PhysicsBody* body)
545	{
546	    if (body->getWorld() != this)
547	    {
548	        CCLOG("Physics Warning: this body doesn't belong to this world");
549	        return;
550	    }
551	    body->_joints.clear();
552	    if (cpSpaceIsLocked(_cpSpace))
553	    {
554	        _delayRemoveBodies.pushBack(body);
555	    }
556	    _bodies.eraseObject(body);
557	    body->_world = nullptr;
558	}
