560	void PhysicsWorld::removeBodyOrDelay(PhysicsBody* body)
561	{
562	    if (_delayRemoveBodies.getIndex(body) == CC_INVALID_INDEX)
563	    {
564	        _delayRemoveBodies.pushBack(body);
565	    }
566	}
