568	void PhysicsWorld::removeJoint(PhysicsJoint* joint, bool destroy)
569	{
570	    if (!joint) return;
571	    joint->_destroyMark = destroy;
572	    if (std::find(_delayRemoveJoints.begin(), _delayRemoveJoints.end(), joint) == _delayRemoveJoints.end())
573	    {
574	        _delayRemoveJoints.push_back(joint);
575	    }
576	}
