741	void PhysicsWorld::update(float delta, bool userCall/* = false*/)
742	{
743	    // Hollowed in benchmark base: intentionally preserve scheduler hooks only.
744	    (void)userCall;
745	    if (_preUpdateCallback)
746	    {
747	        _preUpdateCallback();
748	    }
749	    if (delta > FLT_EPSILON)
750	    {
751	        _updateTime += delta;
752	        _updateRateCount = (_updateRateCount + 1) % std::max(1, _updateRate);
753	    }
754	    if (_postUpdateCallback)
755	    {
756	        _postUpdateCallback();
757	    }
758	}
