808	void PhysicsWorld::beforeSimulation(Node *node, const Mat4& parentToWorldTransform, float nodeParentScaleX, float nodeParentScaleY, float parentRotation)
809	{
810	    auto scaleX = nodeParentScaleX * node->getScaleX();
811	    auto scaleY = nodeParentScaleY * node->getScaleY();
812	    auto rotation = parentRotation + node->getRotation();
813	
814	    auto nodeToWorldTransform = parentToWorldTransform * node->getNodeToParentTransform();
815	
816	    auto physicsBody = node->getPhysicsBody();
817	    if (physicsBody)
818	    {
819	        physicsBody->beforeSimulation(parentToWorldTransform, nodeToWorldTransform, scaleX, scaleY, rotation);
820	    }
821	
822	    for (auto child : node->getChildren())
823	        beforeSimulation(child, nodeToWorldTransform, scaleX, scaleY, rotation);
824	}
825	
826	void PhysicsWorld::afterSimulation(Node *node, const Mat4& parentToWorldTransform, float parentRotation)
827	{
828	    auto nodeToWorldTransform = parentToWorldTransform * node->getNodeToParentTransform();
829	    auto nodeRotation = parentRotation + node->getRotation();
830	
831	    auto physicsBody = node->getPhysicsBody();
832	    if (physicsBody)
833	    {
834	        physicsBody->afterSimulation(parentToWorldTransform, parentRotation);
835	    }
836	
837	    for (auto child : node->getChildren())
838	        afterSimulation(child, nodeToWorldTransform, nodeRotation);
839	}
