void PhysicsWorld::update(float delta, bool userCall/* = false*/)
{
    // Hollowed in benchmark base: intentionally preserve scheduler hooks only.
    (void)userCall;
    if (_preUpdateCallback)
    {
        _preUpdateCallback();
    }
    if (delta > FLT_EPSILON)
    {
        _updateTime += delta;
        _updateRateCount = (_updateRateCount + 1) % std::max(1, _updateRate);
    }
